O = {
"c407:xo53_2_4": ("**가로골절**의 외력", "비틀림 외력은 **나선골절**을 만들어요. 가로골절은 직접 타격이나 굽힘 외력으로 생겨요.", "비틀림 외력으로 생기는 골절은 **나선골절**이다.", "비틀면 나선, 꺾으면 가로", 3),
"c407:xo52_2_3": ("**포크 모양** 변형", "포크 모양 변형은 먼쪽 조각이 손등쪽으로 밀린 **콜리스 골절**이에요. 스미스 골절은 손바닥쪽으로 밀려 정원삽(삽) 모양이에요.", "포크 모양 변형은 **콜리스 골절**에서 생긴다.", "콜리스 포크(등쪽), 스미스 삽(손바닥쪽)", 4),
"c407:xo51_2_4": ("**생목골절** 호발 연령", "생목골절은 뼈가 유연한 **소아**에서 흔해요. 한쪽만 부러지고 반대쪽은 휘어요.", "생목골절은 **소아**에서 흔하다.", "어린 나무가지처럼 휘며 부러진다", 3),
"c407:xo50_1_70": ("**빗장뼈 골절** 위치", "빗장뼈 골절은 **중간 1/3**에서 가장 흔해요.", "빗장뼈 골절은 **중간 1/3**에서 가장 흔하다.", "빗장뼈는 가운데가 약하다", 3),
"c407:xo50_1_72": ("**코담배갑** 압통", "코담배갑 압통은 **손배뼈 골절**의 특징이에요. 혈액 공급이 나빠 무혈성 괴사 위험이 있어요.", "코담배갑 압통은 **손배뼈 골절**의 특징이다.", "코담배갑 = 손배뼈", 4),
"c407:xo50_2_3": ("**복서 골절** 위치", "복서 골절은 **다섯째 손허리뼈 목** 골절이에요. 엄지 손허리뼈 바닥 골절은 베넷 골절이에요.", "복서 골절은 **다섯째 손허리뼈 목** 골절이다.", "복서 = 새끼 쪽, 베넷 = 엄지 바닥", 4),
"c408:xo53_2_9": ("**뼈관절염**의 성격", "뼈관절염은 체중지지 관절의 **연골 퇴행** 질환이에요. 전신 자가면역 질환은 류마티스관절염이에요.", "뼈관절염은 **연골 퇴행성** 질환이다.", "뼈관절염 = 닳음, 류마티스 = 면역", 4),
"c408:xo52_2_9": ("**헤베르덴 결절**", "헤베르덴 결절(DIP)은 **뼈관절염**의 소견이에요. 류마티스관절염은 작은 관절을 대칭적으로 침범해요.", "헤베르덴 결절은 **뼈관절염**의 특징이다.", "헤베르덴 DIP, 부샤르 PIP = 뼈관절염", 4),
"c408:xo51_2_8": ("류마티스관절염 **아침 강직**", "류마티스관절염의 아침 강직은 보통 **1시간 이상** 가요. 30분 이내는 뼈관절염이에요.", "류마티스관절염의 아침 강직은 보통 **1시간 이상**이다.", "류마티스 1시간+, 뼈관절염 30분-", 4),
"c408:xo51_2_9": ("**강직척추염**과 유연성", "강직척추염은 척추 인대가 굳어 대나무 척추가 되면서 유연성이 **감소**해요.", "강직척추염은 척추 유연성이 **감소**하는 질환이다.", "강직 = 굳는다", 4),
"c408:xo50_2_8": ("**백조목** 변형의 PIP", "백조목 변형은 **PIP 과다폄·DIP 굽힘**이에요. PIP가 굽혀지는 것은 단추구멍 변형이에요.", "백조목 변형은 몸쪽 손가락뼈사이관절이 **과다폄**된다.", "백조목 PIP 젖힘, 단추구멍 PIP 굽힘", 5),
"c408:xo50_2_9": ("**통풍**의 원인", "통풍은 퓨린 대사 이상으로 **요산**이 쌓이는 질환이에요. 맞는 문장이에요.", "'칼슘 대사 장애'로 바꾸면 틀려요.", "통풍 = 퓨린 → 요산", 3),
"c408:xo50_2_29": ("류마티스관절염 **관절 보호**", "류마티스관절염은 작은 관절 부담을 줄이고 **큰 관절**을 쓰도록 해요. 연필은 굵게 해 가볍게 쥐어요.", "류마티스관절염 환자는 작은 관절 부담을 **줄이도록** 한다.", "꽉 쥐지 말고 큰 관절로", 3),
"c409:xo53_2_17": ("뼈엉성증과 **몸통 굽힘**", "뼈엉성증에서 몸통 굽힘은 **척추 압박골절** 위험을 높여요. 체중부하·폄 운동을 권해요.", "뼈엉성증에는 몸통 굽힘을 **피한다**.", "뼈엉성증 = 굽히지 말고 서서 걷기", 4),
"c409:xt53_2_17": ("뼈 소실 **지연** 운동", "뼈에 부하가 걸리는 **체중부하 운동**이 뼈 소실을 늦춰요.", "'수중운동'이나 '몸통 굽힘 운동'으로 바꾸면 틀려요.", "뼈는 무게를 받아야 단단해진다", 4),
"c410:xo52_2_1": ("**뼈되기근육염**의 시작", "뼈되기근육염은 외상 후 근육 안에 뼈가 생기는 것으로, **국소** 압통·종괴·운동 제한이 나타나요.", "뼈되기근육염은 외상 후 **국소** 압통으로 시작한다.", "다친 근육에 뼈가 생긴다", 3),
"c410:xt52_2_1": ("뼈되기근육염 **임상양상**", "외상 부위 근육의 **국소 압통·종괴**와 운동 제한이 특징이에요.", "'전신 발열'로 바꾸면 틀려요.", "국소 덩어리", 3),
"c410:xo51_2_3": ("**섬유근육통**과 **근막통증증후군**", "섬유근육통은 **전신** 압통점이 특징이에요. 국소 통증유발점과 연관통은 근막통증증후군이에요.", "국소 통증유발점과 연관통은 **근막통증증후군**의 특징이다.", "전신 = 섬유근육통, 유발점 = 근막통", 4),
"c410:xt51_2_3": ("단단한 띠 + **연관통**", "근육의 단단한 띠 안 통증유발점과 연관통 패턴은 **근막통증증후군**이에요.", "'섬유근육통'으로 바꾸면 틀려요.", "유발점 = 근막통", 4),
"c410:xo51_2_6": ("**파제트병**", "파제트병은 **노인**의 뼈 재형성 이상 질환이에요. 성장기 아동의 세균 감염은 골수염이에요.", "파제트병은 노인의 **뼈 재형성 이상** 질환이다.", "파제트 = 노인 뼈 리모델링", 3),
"c410:xt51_2_6": ("성장기 남아 **뼈몸통끝** 감염", "성장기 긴뼈 뼈몸통끝에 생기는 세균 감염은 **골수염**이에요.", "'파제트병'으로 바꾸면 틀려요.", "아이 뼈 감염 = 골수염", 3),
"c412:xo53_1_80": ("**안굽이무릎** 시기", "안굽이무릎(O다리)은 **2세 이전**에 흔해요. 3~5세에 흔한 것은 밖굽이무릎(X다리)이에요.", "3~5세에 흔한 것은 **밖굽이무릎**이다.", "O다리 아기, X다리 유아", 3),
"c412:xt53_1_80": ("3~5세 **이마면** 기형", "3~5세에 흔한 이마면 기형은 **밖굽이무릎(X다리)** 이에요.", "'안굽이무릎'으로 바꾸면 틀려요.", "O → X → 곧게", 3),
"c412:xo50_2_2": ("**선천 기운목**의 근육", "선천 기운목은 **목빗근**이 짧아져 같은 쪽으로 기울고 반대쪽으로 돌아가요.", "선천 기운목은 **목빗근**이 짧아져 생긴다.", "기운목 = 목빗근", 4),
"c412:xt50_2_2": ("기운목에서 **뻗칠 근육**", "분만 외상 혈종 후 생기는 선천 기운목은 **목빗근**을 뻗쳐요.", "'등세모근'으로 바꾸면 틀려요.", "기운목 = 목빗근", 4),
"c412:xo50_2_5": ("넙다리뼈 **목-몸통각**", "정상 성인 목-몸통각은 약 **125°** 예요. 맞는 문장이에요. 작으면 안굽이, 크면 밖굽이예요.", "'약 150°'로 바꾸면 틀려요.", "125 기준, 작으면 내반", 4),
"c413:xo53_2_7": ("척주옆굽음증 **오목한 쪽**", "오목한 쪽 근육은 짧아져 있어 **뻗치고**, 볼록한 쪽을 강화해요.", "척주옆굽음증에서는 오목한 쪽 근육을 **뻗친다**.", "오목 = 짧다 = 늘리기", 4),
"c413:xt53_2_7": ("가쪽굽이 + **돌림**", "가쪽굽이와 돌림이 함께 있고 오목한 쪽 뻗침·볼록한 쪽 강화를 하는 것은 **척주옆굽음증**이에요.", "'척추전방전위증'으로 바꾸면 틀려요.", "옆굽음 = 옆 + 돌림", 4),
"c413:xo52_1_75": ("**갈비뼈 융기** 위치", "구조적 척주옆굽음에서 갈비뼈 융기는 **볼록한 쪽** 뒤로 생겨요.", "갈비뼈 융기는 **볼록한 쪽**에 생긴다.", "튀어나온 쪽 = 볼록한 쪽", 4),
"c413:xt52_1_75": ("척추뼈몸통 **돌림 방향**", "구조적 옆굽음에서 척추뼈몸통은 **볼록한 쪽**으로 돌아가요. 왼쪽 볼록이면 왼쪽이에요.", "'오목한 쪽(오른쪽)'으로 바꾸면 틀려요.", "몸통은 볼록 쪽으로 돈다", 3),
"c413:xo50_2_19": ("척주옆굽음 **뻗침 쪽**", "짧아진 **오목한 쪽**을 뻗치고 볼록한 쪽을 강화해요.", "척주옆굽음에서는 **오목한 쪽** 근육을 뻗친다.", "오목 = 늘리기, 볼록 = 키우기", 4),
"c413:xt50_2_19": ("오른쪽 볼록 → **뻗칠 쪽**", "오른쪽이 볼록하면 왼쪽이 오목하므로 **등뼈 왼쪽 척추주변근**을 뻗쳐요.", "'오른쪽'으로 바꾸면 틀려요.", "볼록 반대편을 늘린다", 4),
"c414:xo52_1_78": ("맥머리 **안쪽돌림**", "정강뼈 안쪽돌림 맥머리는 **가쪽반달**을, 바깥돌림은 안쪽반달을 봐요.", "정강뼈 안쪽돌림 맥머리 검사는 **가쪽반달**을 본다.", "돌림 방향과 반대 반달", 4),
"c414:xt52_1_78": ("안쪽돌림 맥머리 **딸깍**", "정강뼈 안쪽돌림에서 딸깍 소리가 나면 **가쪽반달** 손상이에요.", "'안쪽반달'로 바꾸면 틀려요.", "안쪽돌림 = 가쪽반달", 4),
"c414:xo51_1_79": ("**바운스 홈** 검사", "끝 폄이 막혀 튕겨 돌아오면 찢긴 **반달연골**이 관절에 끼인 거예요.", "바운스 홈 검사 양성은 **반달연골** 손상을 뜻한다.", "튕겨 나오면 반달", 3),
"c414:xt51_1_79": ("끝까지 못 펴고 **다시 굽는** 무릎", "찢긴 **반달연골**이 끼여 끝 폄이 막혀요.", "'뒤십자인대'로 바꾸면 틀려요.", "잠김 = 반달", 3),
"c414:xo50_1_34": ("무릎뼈 **가쪽 치우침**", "가쪽넓은근은 무릎뼈를 더 가쪽으로 당기므로 **안쪽넓은근(빗근)** 을 강화해요.", "무릎뼈 가쪽 치우침에는 **안쪽넓은근**을 강화한다.", "가쪽으로 쏠리면 안쪽을 키운다", 5),
"c414:xt50_1_34": ("무릎뼈 가쪽 치우침 **강화 근육**", "무릎뼈를 안쪽으로 잡아 주는 **안쪽넓은근(빗근)** 을 강화해요.", "'가쪽넓은근'으로 바꾸면 틀려요.", "VMO", 5),
"c407:xo53_2_8": ("**무릎뼈 탈구** 방향", "Q각이 크면 넙다리네갈래근이 무릎뼈를 가쪽으로 당겨, 무릎뼈 탈구는 대부분 **가쪽**으로 일어나요.", "무릎뼈 탈구는 대부분 **가쪽**으로 일어난다.", "무릎뼈는 바깥으로 빠진다", 4),
"c314:xo53_1_30": ("**가쪽넓은근** 작용", "가쪽넓은근은 무릎뼈를 **가쪽**으로 당겨요. 안쪽으로 당겨 안정시키는 것은 안쪽넓은근이에요.", "가쪽넓은근은 무릎뼈를 **가쪽**으로 당긴다.", "이름 방향으로 당긴다", 4),
"c416:xo50_1_76": ("**레그-칼베-페르테스병**", "소아 넙다리뼈머리의 **무혈성 괴사**가 레그-칼베-페르테스병이에요. 맞는 문장이에요.", "'넙다리뼈 머리 미끄러짐증'으로 바꾸면 틀려요(그건 넙다리뼈머리 뼈끝 미끄러짐).", "소아 무혈성 괴사 = 페르테스", 4),
"c417:xo51_2_27": ("**러시안전류**의 용도", "러시안전류는 **근력 강화**용이에요. 발바닥근막염의 통증·조직치유에는 초음파를 써요.", "러시안전류는 **근력 강화**에 쓴다.", "러시안 = 근력", 3),
"c417:xt51_2_27": ("발바닥근막염 **조직치유**", "발바닥근막염의 통증 감소와 조직치유에는 **초음파**를 써요.", "'러시안전류'로 바꾸면 틀려요.", "조직치유 = 초음파", 3),
"c418:xo53_2_50": ("**S1** 손상 강화 운동", "S1은 장딴지근(발바닥굽힘)을 맡으므로 **발바닥굽힘**을 강화해요. 발등굽힘은 L4예요.", "S1 손상에는 **발바닥굽힘** 강화가 우선이다.", "S1 = 까치발", 4),
"c418:xt53_2_50": ("발 가쪽 감각↓ + **장딴지근 약화**", "S1 손상이므로 **발가락·발바닥굽힘 강화** 운동을 해요.", "'발등굽힘 강화'로 바꾸면 틀려요.", "S1 = 발바닥굽힘", 4),
"c418:xo53_2_64": ("원반탈출 **운동 선택**", "앉거나 굽히면 악화되는 원반탈출에는 **맥켄지(폄)** 운동이 알맞아요. 윌리엄 굽힘 운동은 펴면 악화되는 척추관협착에 써요.", "굽히면 악화되는 원반탈출에는 **맥켄지 폄 운동**이 우선이다.", "원반 = 폄, 협착 = 굽힘", 5),
"c418:xt53_2_64": ("앉으면 악화, **걸으면 완화**", "굽힘에서 악화되는 원반탈출이므로 **맥켄지(폄) 운동**을 해요.", "'윌리엄 굽힘 운동'으로 바꾸면 틀려요.", "원반 = 폄", 5),
"c418:xo52_2_8": ("**L5** 뿌리 압박", "L5 뿌리 압박은 **긴엄지발가락폄근**이 약해져요. 아킬레스 반사는 S1이에요.", "L5 뿌리 압박에서는 **긴엄지발가락폄근**이 약해진다.", "L4 무릎반사, L5 엄지 폄, S1 아킬레스", 5),
"c418:xt52_2_8": ("L4-5 **뒤가쪽** 탈출 증상", "L4-5 뒤가쪽 탈출은 L5 뿌리를 눌러 **긴엄지발가락폄근 약화**가 나타나요.", "'아킬레스 반사 소실'로 바꾸면 틀려요.", "L5 = 엄지 들기", 5),
"c419:xo53_2_20": ("**엎침** 증가 미끄러짐", "엎침을 늘리려면 노뼈머리를 **손등쪽**으로, 뒤침은 손바닥쪽으로 미끄러뜨려요.", "엎침을 늘리려면 노뼈머리를 **손등쪽**으로 민다.", "엎침 손등, 뒤침 손바닥", 3),
"c419:xo53_2_23": ("정강뼈 **뒤쪽** 미끄러짐", "정강뼈 관절면은 오목해 움직임과 같은 방향으로 미끄러져요. 뒤쪽 미끄러짐은 **굽힘**을 늘리고, 폄은 앞쪽이에요.", "정강뼈 뒤쪽 미끄러짐은 무릎 **굽힘**을 늘린다.", "오목 = 같은 방향", 5),
"c419:xo52_2_19": ("무릎 굽힘과 **무릎뼈**", "무릎을 굽히면 무릎뼈가 **아래쪽(먼쪽)** 으로 내려가야 하므로 굽힘 제한엔 아래쪽 미끄러짐을 줘요.", "무릎 굽힘을 늘리려면 무릎뼈를 **아래쪽**으로 민다.", "굽힘 = 무릎뼈 아래로", 4),
"c419:xo52_2_20": ("**발꿈치뼈**와 가쪽번짐", "발꿈치뼈 관절면은 볼록해 움직임과 반대로 미끄러져요. 가쪽번짐은 **안쪽 미끄러짐**이에요.", "가쪽번짐을 늘리려면 발꿈치뼈를 **안쪽**으로 미끄러뜨린다.", "볼록 = 반대 방향", 4),
"c419:xo52_2_21": ("넙다리뼈머리 **앞쪽** 미끄러짐", "볼록한 넙다리뼈머리는 반대로 미끄러져요. 앞쪽 미끄러짐은 **폄**, 굽힘은 뒤쪽이에요.", "넙다리뼈머리 앞쪽 미끄러짐은 엉덩관절 **폄**을 늘린다.", "볼록 = 반대 방향", 5),
"c419:xo52_2_23": ("**가로돌기** 한쪽 밀기", "한쪽 가로돌기를 앞으로 밀면 척추가 **돌아가요**(돌림 증가). 가시돌기 중앙을 밀면 폄이 늘어요.", "가로돌기 한쪽을 밀면 척추 **돌림**이 늘어난다.", "가운데 = 폄, 옆 = 돌림", 3),
"c419:xo51_2_19": ("위팔뼈와 **바깥돌림**", "볼록한 위팔뼈머리는 반대로 미끄러져, 바깥돌림은 **앞쪽** 미끄러짐이에요.", "위팔뼈 **앞쪽** 미끄러짐은 바깥돌림을 늘린다.", "바깥돌림 앞, 안쪽돌림 뒤", 5),
"c419:xo51_2_22": ("목말뼈와 **발등굽힘**", "볼록한 목말뼈는 반대로 미끄러져, 발등굽힘은 **뒤쪽** 미끄러짐이에요.", "발등굽힘을 늘리려면 목말뼈를 **뒤쪽**으로 미끄러뜨린다.", "발등굽힘 = 목말뼈 뒤로", 5),
"c419:xo51_2_23": ("가시돌기 **중앙** 밀기", "가시돌기 중앙을 앞으로 밀면 **폄**이 늘어요. 돌림은 가로돌기 쪽을 밀어요.", "가시돌기 중앙 앞쪽 밀기는 **폄**을 늘린다.", "가운데 = 폄", 3),
"c419:xo50_2_21": ("팔꿉 폄과 **노뼈머리**", "오목한 노뼈머리는 움직임과 같은 방향이라 폄은 **손등쪽**으로 미끄러뜨려요.", "팔꿉 폄을 늘리려면 노뼈머리를 **손등쪽**으로 미끄러뜨린다.", "오목 = 같은 방향", 3),
"c419:xo50_2_23": ("손목 폄과 **손목뼈**", "볼록한 손목뼈는 반대로 미끄러져, 손목 폄은 **손바닥쪽**이에요.", "손목 폄을 늘리려면 손목뼈를 **손바닥쪽**으로 미끄러뜨린다.", "볼록 = 반대 방향", 4),
"c420:xo53_2_22": ("**근방호** 끝느낌", "근방호는 통증·방어가 앞서므로 부드러운 **1등급 관절가동술**로 통증부터 조절해요.", "근방호가 있으면 **부드러운 1등급 관절가동술**로 통증을 조절한다.", "방어하면 부드럽게", 3),
"c420:xt53_2_22": ("골절 없는 **근방호** 치료", "통증·방어가 우선이라 **부드러운 1등급 관절가동술**을 써요.", "'고강도 저항운동'으로 바꾸면 틀려요.", "근방호 = 1등급", 3),
"c420:xo52_1_63": ("**반달연골 열상** 끝느낌", "반달연골 열상은 **튕기는(springy)** 끝느낌이에요. 뼈-뼈 느낌은 뼈곁돌기 등이에요.", "반달연골 열상의 끝느낌은 **튕기는** 느낌이다.", "반달 = 튕김", 4),
"c420:xt52_1_63": ("굽힘 끝범위 **뼈-뼈**", "무릎 굽힘 끝에서 뼈-뼈 끝느낌이 나면 **뼈곁돌기(골극) 형성**을 의심해요.", "'반달연골 열상'으로 바꾸면 틀려요.", "딱 = 뼈", 4),
"c420:xo50_1_63": ("팔꿉 폄의 **정상 끝느낌**", "팔꿉 폄은 팔꿈치머리가 오목에 닿는 **단단한(뼈)** 끝느낌이 정상이에요. 부드러운 끝느낌은 무릎·팔꿉 굽힘이에요.", "팔꿉 폄의 정상 끝느낌은 **단단한(뼈)** 끝느낌이다.", "팔꿉 폄 = 뼈, 굽힘 = 물렁조직", 4),
"c420:xt50_1_63": ("**부드러운** 끝느낌", "종아리와 넙다리가 맞닿는 **무릎 굽힘**은 부드러운 끝느낌이에요.", "'팔꿉 폄'으로 바꾸면 틀려요.", "살끼리 닿으면 부드럽다", 4),
"c421:xo53_2_21": ("관절가동술 **4등급**", "3등급은 큰 진폭, **4등급은 작은 진폭**으로 제한점까지 들어가요.", "4등급은 **작은 진폭** 진동이다.", "1·4 작게, 2·3 크게", 5),
"c421:xo53_2_24": ("환자의 **자발적 수축** 이용", "환자의 조절된 등척성 수축 후 이완을 이용하는 것은 **근에너지기법**이에요. 근막이완술은 치료사가 지속 압력을 줘요.", "환자의 자발적 근수축을 이용하는 것은 **근에너지기법**이다.", "환자가 힘쓰면 근에너지", 3),
"c421:xo52_2_12": ("**통증 완화** 등급", "통증 완화에는 저항 전 범위의 **1·2등급**을 써요. 3·4등급은 범위 증가용이에요.", "통증 완화에는 저항 전 **1·2등급** 진동을 쓴다.", "통증 1·2, 범위 3·4", 5),
"c421:xo52_2_22": ("**채찍손상** 초기", "급성기에는 보호·안정이 우선이라 3등급 견인은 피하고 **등척운동**부터 시작해요.", "채찍손상 초기에는 **보호·안정**과 등척운동부터 한다.", "급성기는 지킨다", 3),
"c421:xo51_2_24": ("목뼈 견인과 **척추사이구멍**", "견인하면 척추사이구멍이 **넓어져** 신경뿌리 압박이 줄어요.", "목뼈 견인을 하면 척추사이구멍이 **넓어진다**.", "당기면 넓어진다", 4),
"c421:xo51_2_25": ("**2등급** 범위", "2등급은 조직 저항 **전**까지 큰 진폭이에요. 저항까지 들어가는 것은 3등급이에요.", "**3등급**은 조직 저항이 느껴지는 범위까지 들어간다.", "2는 저항 전, 3은 저항까지", 5),
"c423:xo53_2_25": ("**들어 올려 짜기**", "근육을 들어 올려 짜는 것은 **주무르기(페트리사지)** 예요. 쓰다듬기는 미끄러지듯 하는 얕은 기법이에요.", "근육 덩어리를 들어 올려 짜는 것은 **주무르기**다.", "짜기 = 주무르기", 3),
"c423:xt53_2_25": ("들어 올리거나 **짜는** 마사지", "근육을 들어 올리고 짜는 것이 **주무르기(페트리사지)** 예요.", "'쓰다듬기'로 바꾸면 틀려요.", "짜기 = 주무르기", 3),
"c423:xo51_2_18": ("**쓰다듬기**의 효과", "쓰다듬기는 **이완·진정** 효과예요. 근육을 강하게 자극하는 것은 두드리기예요.", "쓰다듬기는 **이완**을 위한 기법이다.", "쓰다듬기 이완, 두드리기 자극", 3),
"c423:xt51_2_18": ("**자극 효과** 마사지", "근수축을 자극하고 경기력을 높이는 것은 **두드리기(타포트망)** 예요.", "'쓰다듬기'로 바꾸면 틀려요.", "두드리면 깨어난다", 3),
"c423:xo50_2_22": ("**흉터 유착** 풀기", "흉터 유착에는 깊게 누르며 문지르는 **문지르기(마찰)** 가 효과적이에요.", "흉터 유착을 떼는 데는 **문지르기**가 효과적이다.", "유착 = 문지르기", 3),
"c423:xt50_2_22": ("깊게 누르며 **유착 풀기**", "유착된 흉터를 풀기 위해 깊게 누르며 하는 것이 **문지르기(friction)** 예요.", "'쓰다듬기'로 바꾸면 틀려요.", "유착 = 문지르기", 3),
"c424:xo53_2_16": ("**작용근 수축** 기법", "작용근 수축 기법은 짧아진 근육의 **반대쪽(작용근)** 을 수축시켜 상호억제로 짧은 근육을 이완시켜요.", "작용근 수축 기법에서는 짧아진 근육의 **반대쪽 근육**을 수축시킨다.", "반대편을 쓰면 이쪽이 풀린다", 4),
"c424:xo52_2_13": ("무릎 가쪽 통증 + **큰돌기주머니염**", "이 증상들은 넙다리근막긴장근(엉덩정강근막띠) **단축**과 관련 있어 강화가 아니라 **뻗침**이 필요해요.", "이 환자에게는 넙다리근막긴장근 **뻗침**이 필요하다.", "짧아서 아프면 늘린다", 3),
"c424:xo52_2_14": ("**기계적 뻗침**", "기계적 뻗침은 **낮은 부하를 오래(수십 분~수시간)** 걸어 결합조직의 크리프·소성변형을 노려요.", "기계적 뻗침은 **낮은 강도로 오래** 한다.", "약하게 오래 = 크리프", 4),
"c424:xo52_2_24": ("반대쪽 **윗가슴** 누르며 늘리기", "머리를 고정하고 반대쪽 윗가슴을 누르며 날숨에 늘리는 것은 첫째 갈비뼈에 닿는 **목갈비근** 뻗침이에요.", "이 기법은 **목갈비근**을 늘린다.", "갈비뼈를 내리면 목갈비근", 3),
"c425:xo53_2_11": ("인대 수술 후 **초기** 운동", "고정을 줄이는 초기에는 관절을 움직이지 않는 **다각도 최대하 등척운동**을 해요. 점프는 후기 운동이에요.", "고정을 줄이는 초기에는 **다각도 최대하 등척운동**을 한다.", "초기 등척, 후기 점프", 4),
"c425:xo52_2_11": ("**드로름** 기법", "드로름 기법은 10RM의 50 → 75 → 100%로 무게를 **늘려요**. 줄이는 것은 옥스퍼드 기법이에요.", "드로름 기법은 무게를 점점 **늘린다**.", "드로름 올리기, 옥스퍼드 내리기", 5),
"c425:xo52_2_25": ("**덤벨**과 중력", "덤벨은 **중력 방향** 저항이에요. 중력에 의존하지 않는 것은 늘어난 만큼 저항이 생기는 탄성밴드예요.", "**탄성밴드**는 중력에 의존하지 않는 저항 기구다.", "덤벨 = 중력, 밴드 = 탄성", 3),
"c425:xo51_2_11": ("**맨손저항운동** 단점", "맨손저항운동은 근력 향상을 **정량화하기 어려운** 것이 단점이에요.", "맨손저항운동은 근력 향상을 정량적으로 측정하기 **어렵다**.", "손 힘은 숫자가 없다", 3),
"c425:xo51_2_16": ("저항운동과 **동시발화**", "저항운동 초기 근력 증가는 신경 적응, 즉 운동단위 동원과 동시발화의 **증가** 때문이에요.", "저항운동을 하면 운동단위 동시발화가 **증가**한다.", "초기 근력 = 신경 적응", 4),
"c425:xo51_2_64": ("**점프 능력** 향상", "점프 능력은 신장-단축 주기를 쓰는 **플라이오메트릭** 운동이 가장 적합해요.", "점프 능력 향상에는 **플라이오메트릭 운동**이 가장 적합하다.", "점프 = 플라이오", 4),
"c425:xo50_2_16": ("**등속성 운동**", "등속성 운동은 **각속도가 일정**하고 저항이 근력에 맞춰 바뀌어요. 같은 무게를 드는 것은 등장성이에요.", "등속성 운동은 전 범위에서 **각속도가 일정**하다.", "등속 = 속도 고정, 등장 = 무게 고정", 5),
"c426:xo53_2_14": ("**닫힌사슬** 운동의 장점", "닫힌사슬 운동은 여러 관절의 **협응**과 체중부하 기능 훈련에 좋아요. 개별 근육 강화는 열린사슬이 유리해요.", "**열린사슬 운동**이 개별 근육 강화에 더 효과적이다.", "닫힌 = 협응, 열린 = 개별 근육", 4),
"c426:xt53_2_14": ("닫힌사슬 운동 **장점**", "발이 땅에 붙은 닫힌사슬 운동은 **여러 관절의 협응**에 효과적이에요.", "'개별 근육 강화'로 바꾸면 틀려요.", "닫힌 = 협응", 4),
"c428:xo53_2_10": ("**진자운동** 목적", "진자(코드만) 운동은 팔 무게로 위팔뼈를 견인해 **이완·통증 감소**를 돕는 운동이에요. 근력 증진 운동이 아니에요.", "진자운동은 **이완·통증 감소**가 목적이다.", "흔들면 당겨진다", 4),
"c428:xo53_2_12": ("**급성기** 유착 예방", "급성기에는 통증 없는 범위의 **수동운동**으로 조직을 보호하며 유착을 막아요. 저항운동은 회복기예요.", "급성기에는 **통증 없는 범위의 수동운동**으로 유착을 막는다.", "급성기 = 수동", 4),
"c428:xo51_2_10": ("급성 발목 염좌 **초기**", "급성기는 **보호**가 우선이라 부드러운 범위 운동만 해요. 3등급 가동술은 염증이 가라앉은 뒤예요.", "급성 발목 염좌에는 **보호**와 부드러운 범위 운동을 먼저 한다.", "급성 = 보호", 4),
"c428:xo51_2_12": ("**스케이트보드** 엉덩관절 운동", "보드가 마찰을 줄여 약한 근육이 스스로 움직이게 돕는 **능동보조운동**이에요. CPM은 기계가 관절을 움직여요.", "스케이트보드 운동은 **능동보조운동**에 해당한다.", "마찰을 줄여 돕는다 = 능동보조", 3),
"c428:xo51_2_17": ("**진자운동** 목적", "진자운동은 부드러운 **견인**과 관절범위 증진이 목적이에요.", "진자운동은 부드러운 **견인**으로 관절범위를 늘리는 운동이다.", "흔들기 = 견인", 4),
"c428:xo50_2_25": ("근력 **가(P)** 등급 운동", "가 등급은 중력을 이기지 못하므로 **중력 제거 자세 능동운동**부터 시작해요.", "근력 가 등급이면 **중력 제거 자세** 능동운동부터 시작한다.", "가 = 중력 빼고", 4),
"c431:xo52_2_65": ("돌림근띠 수술 **3일째**", "봉합 3일째는 최대 보호기라 통증 없는 범위의 **낮은 강도 근고정(등척)** 만 하고, 완전범위 뻗침은 금지예요.", "수술 3일째에는 **낮은 강도 근고정 운동**만 한다.", "봉합 직후 = 지키기", 4),
"c431:xt52_2_65": ("돌림근띠 수술 3일 **운동**", "최대 보호기이므로 **낮은 강도 근고정(등척) 운동**을 해요.", "'완전범위 뻗침'으로 바꾸면 틀려요.", "초기 = 근고정", 4),
"c431:xo50_2_10": ("저항 전 통증 = **급성기**", "조직 저항 전에 통증이 오면 급성기라 **근고정 운동**을 해요. 플라이오메트릭은 최소보호기예요.", "급성기에는 **근고정 운동**을 한다.", "통증이 먼저면 급성", 4),
"c431:xt50_2_10": ("저항 전 **통증** 시기 운동", "급성기이므로 **근고정(등척성) 운동**을 해요.", "'플라이오메트릭'으로 바꾸면 틀려요.", "급성 = 근고정", 4),
"c431:xo50_2_15": ("**석고 고정 중** 운동", "고정 중에는 관절을 움직이지 않는 **등척성** 운동을 해요.", "석고 고정 중에는 **등척성 운동**을 한다.", "고정 = 등척", 4),
"c431:xt50_2_15": ("석고 고정 중 **가능한 운동**", "관절을 움직이지 않고 근수축만 하는 **등척성 운동**이에요.", "'관절운동범위 운동'으로 바꾸면 틀려요.", "고정 = 등척", 4),
"c432:xo53_2_13": ("ACL 수술 **직후**", "ACL 수술 직후에는 **CPM**으로 범위를 천천히 늘려요. 플라이오메트릭은 복귀 직전 후기 운동이에요.", "ACL 수술 직후에는 **CPM**을 한다.", "수술 직후 = CPM", 4),
"c432:xt53_2_13": ("ACL 수술 직후 **연속 운동**", "속도·범위를 조절하며 기계가 연속으로 움직이는 **지속적수동운동(CPM)** 이에요.", "'플라이오메트릭'으로 바꾸면 틀려요.", "수술 직후 = CPM", 4),
"c432:xo53_2_29": ("엉덩관절 치환 후 **의자**", "뒤쪽 접근 치환술 후에는 90° 넘는 굽힘을 피해야 해서 **높은 의자**에 무릎이 엉덩관절보다 약간 낮게 앉아요.", "엉덩관절 치환 후에는 **높은 의자**에 앉아 굽힘을 줄인다.", "치환 후 = 90° 넘기지 않기", 4),
"c432:xt53_2_29": ("치환술 후 **의자 높이**", "굽힘을 90° 이하로 유지하도록 **무릎을 엉덩관절보다 약간 낮게** 앉아요.", "'낮은 의자'로 바꾸면 틀려요.", "무릎이 엉덩이보다 아래", 4),
"c432:xo51_2_15": ("무릎관절성형술 **직후**", "수술 직후에는 기계가 천천히 움직이는 **CPM**으로 범위 회복을 도와요. 등속성 운동은 후기예요.", "무릎관절성형술 직후에는 **CPM**부터 시작한다.", "수술 직후 = CPM", 4),
"c432:xt51_2_15": ("무릎관절성형술 직후 **범위 회복**", "수술 직후 관절운동범위 회복에는 **지속적수동운동(CPM)** 을 써요.", "'등속성운동'으로 바꾸면 틀려요.", "수술 직후 = CPM", 4),
"c432:xo50_2_13": ("**발목 펌핑** 운동", "발목 펌핑은 장딴지 근육 펌프로 정맥 귀환을 늘려 깊은정맥혈전증을 예방해요. 맞는 문장이에요.", "'깊은정맥혈전증을 일으킨다'고 하면 틀려요.", "발목 펌프 = 정맥 귀환", 4),
"c433:xo53_1_49": ("넙다리 절단 후 **강화 근육**", "넙다리 절단은 굽힘·벌림·바깥돌림 구축 경향이 있어 **폄·모음** 근육을 강화해요.", "넙다리 절단 환자는 엉덩관절 **폄근과 모음근**을 강화해야 한다.", "구축 반대 방향을 키운다", 5),
"c433:xt53_1_49": ("아래팔 절단 **구축 예방**", "아래팔 절단 후에는 팔꿉 굽힘 구축이 잘 생겨 **팔꿉관절 폄 강화**로 예방해요.", "'팔꿉 굽힘 강화'로 바꾸면 틀려요.", "굽힘 구축 = 폄 강화", 4),
"c433:xo53_2_5": ("**리스프랑 절단** 위치", "리스프랑 절단은 **발목발허리관절** 높이 분리절단이에요. 발목관절 바로 위는 사임 절단이에요.", "리스프랑 절단은 **발목발허리관절** 분리절단이다.", "리스프랑 발허리, 쇼파르 발목뼈중간, 사임 발목", 3),
"c433:xt53_2_5": ("**리스프랑** 절단 위치", "발목뼈와 발허리뼈 사이인 **발목발허리관절** 분리절단이에요.", "'발목관절 바로 위'로 바꾸면 틀려요. 그건 사임 절단이에요.", "리스프랑 = 발허리", 3),
"c433:xo51_2_5": ("아래팔 절단 **구축 방향**", "아래팔 절단 후에는 팔꿉 **굽힘** 구축이 잘 생겨요.", "아래팔 절단 후에는 팔꿉관절 **굽힘** 구축이 잘 생긴다.", "남은 근육이 굽힌다", 4),
"c433:xt51_2_5": ("의지 사용을 좌우하는 **잘린끝 길이**", "잘린끝이 **길수록** 지렛대와 엎침·뒤침이 남아 의지 조작이 쉬워요.", "'짧을수록 유리'로 바꾸면 틀려요.", "길수록 유리", 3),
}
